     1→# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
     2→# ABOUTME: Provides methods called by semantic actions to build IR nodes during parsing
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Scope;
    11→
    12→    # Phase 1 polymorphic node classes
    13→    use Chalk::IR::Node::Base;
    14→    use Chalk::IR::Node::Constant;
    15→    use Chalk::IR::Node::Start;
    16→    use Chalk::IR::Node::Return;
    17→    use Chalk::IR::Node::Add;
    18→    use Chalk::IR::Node::Subtract;
    19→    use Chalk::IR::Node::Multiply;
    20→    use Chalk::IR::Node::Divide;
    21→    use Chalk::IR::Node::Negate;
    22→    use Chalk::IR::Node::Not;
    23→    use Chalk::IR::Node::PreIncrement;
    24→    use Chalk::IR::Node::PreDecrement;
    25→    use Chalk::IR::Node::PostIncrement;
    26→    use Chalk::IR::Node::PostDecrement;
    27→    use Chalk::IR::Node::Reference;
    28→    use Chalk::IR::Node::GT;
    29→    use Chalk::IR::Node::LT;
    30→    use Chalk::IR::Node::EQ;
    31→    use Chalk::IR::Node::NE;
    32→    use Chalk::IR::Node::LE;
    33→    use Chalk::IR::Node::GE;
    34→    use Chalk::IR::Node::If;
    35→    use Chalk::IR::Node::Proj;
    36→    use Chalk::IR::Node::Region;
    37→    use Chalk::IR::Node::Phi;
    38→    use Chalk::IR::Node::Loop;
    39→
    40→    field $graph :reader;
    41→    field $scope :reader;
    42→    field $node_counter :reader = 0;
    43→    field $current_control :reader;  # Current control flow node
    44→    field $loop_entry_scope;  # Snapshot of scope bindings at loop entry
    45→    field $loop_tracking_active = 0;  # Whether loop tracking is active
    46→
    47→    ADJUST {
    48→        $graph = Chalk::IR::Graph->new();
    49→        $scope = Chalk::IR::Scope->new();
    50→    }
    51→
    52→    # Generate unique node ID
    53→    method next_node_id() {
    54→        my $id = "node_$node_counter";
    55→        $node_counter++;
    56→        return $id;
    57→    }
    58→
    59→    # Set current control flow node
    60→    method set_control($ctrl) {
    61→        $current_control = $ctrl;
    62→    }
    63→
    64→    # Create Start node for a function/method
    65→    method build_start_node($function_name = 'main', $params = undef) {
    66→        $params //= [];
    67→        my $node_id = $self->next_node_id();
    68→        my $empty_inputs = [];
    69→        my $start = Chalk::IR::Node::Start->new(
    70→            id            => $node_id,
    71→            inputs        => $empty_inputs,
    72→            function_name => $function_name,
    73→            params        => $params,
    74→        );
    75→        $graph->add_node($start);
    76→        $self->set_control($start->id);
    77→
    78→        # Create Proj nodes for each parameter and register in scope
    79→        my $param_count = scalar($params->@*);
    80→        for my $i (0..($param_count - 1)) {
    81→            my $param_name = $params->[$i];
    82→            my $proj = $self->build_proj_node($start, $i, $param_name);
    83→            # Register parameter Proj in scope so lookups return it directly
    84→            $scope->define($param_name, $proj->id);
    85→        }
    86→
    87→        return $start;
    88→    }
    89→
    90→    # Create Constant node
    91→    method build_constant_node($value, $type = 'Int') {
    92→        my $node_id = $self->next_node_id();
    93→        my $constant = Chalk::IR::Node::Constant->new(
    94→            id            => $node_id,
    95→            inputs        => [$current_control],
    96→            value         => $value,
    97→            type          => $type,
    98→        );
    99→        $graph->add_node($constant);
   100→        return $constant;
   101→    }
   102→
   103→    # Create Return node
   104→    # If $control is undef, uses current_control. Otherwise uses provided control.
   105→    method build_return_node($value_node, $control = undef) {
   106→        # Debug: check what we received
   107→        my $ref_type = ref($value_node) || 'SCALAR';
   108→        my $prefix = substr($ref_type, 0, 15);
   109→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
   110→        unless ($ref_type && $is_node) {
   111→            warn "build_return_node received non-node: $ref_type\n";
   112→            return undef;
   113→        }
   114→
   115→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   116→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   117→
   118→        my $node_id = $self->next_node_id();
   119→        my $return = Chalk::IR::Node::Return->new(
   120→            id            => $node_id,
   121→            inputs        => [$ctrl, $value_node->id],
   122→            value_id      => $value_node->id,
   123→            control_id    => $ctrl,
   124→        );
   125→        $graph->add_node($return);
   126→        return $return;
   127→    }
   128→
   129→    # Set control input for an existing node
   130→    method set_node_control($node, $control_id) {
   131→        my $inputs = $node->inputs;
   132→        $inputs->[0] = $control_id;  # Control is always first input
   133→    }
   134→
   135→    # Create arithmetic operation nodes
   136→    method build_add_node($left_node, $right_node) {
   137→        my $node_id = $self->next_node_id();
   138→        my $add = Chalk::IR::Node::Add->new(
   139→            id => $node_id,
   140→            inputs => [$current_control, $left_node->id, $right_node->id],
   141→            left_id => $left_node->id,
   142→            right_id => $right_node->id,
   143→        );
   144→        $graph->add_node($add);
   145→        return $add;
   146→    }
   147→
   148→    method build_multiply_node($left_node, $right_node) {
   149→        my $node_id = $self->next_node_id();
   150→        my $mul = Chalk::IR::Node::Multiply->new(
   151→            id => $node_id,
   152→            inputs => [$current_control, $left_node->id, $right_node->id],
   153→            left_id => $left_node->id,
   154→            right_id => $right_node->id,
   155→        );
   156→        $graph->add_node($mul);
   157→        return $mul;
   158→    }
   159→
   160→    method build_sub_node($left_node, $right_node) {
   161→        my $node_id = $self->next_node_id();
   162→        my $sub = Chalk::IR::Node::Subtract->new(
   163→            id => $node_id,
   164→            inputs => [$current_control, $left_node->id, $right_node->id],
   165→            left_id => $left_node->id,
   166→            right_id => $right_node->id,
   167→        );
   168→        $graph->add_node($sub);
   169→        return $sub;
   170→    }
   171→
   172→    method build_divide_node($left_node, $right_node) {
   173→        my $node_id = $self->next_node_id();
   174→        my $div = Chalk::IR::Node::Divide->new(
   175→            id => $node_id,
   176→            inputs => [$current_control, $left_node->id, $right_node->id],
   177→            left_id => $left_node->id,
   178→            right_id => $right_node->id,
   179→        );
   180→        $graph->add_node($div);
   181→        return $div;
   182→    }
   183→
   184→    # Create Store node (variable assignment)
   185→    method build_store_node($var_name, $value_node, $control = undef) {
   186→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   187→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   188→
   189→        my $value_ref = { op => 'NodeRef', node_id => $value_node->id };
   190→        my $attributes = {
   191→            name => $var_name,
   192→            value => $value_ref
   193→        };
   194→        my $node_id = $self->next_node_id();
   195→        my $store = Chalk::IR::Node->new(
   196→            id            => $node_id,
   197→            op            => 'Store',
   198→            inputs        => [$ctrl, $value_node->id],
   199→            attributes    => $attributes,
   200→        );
   201→        $graph->add_node($store);
   202→        $scope->define($var_name, $store->id);
   203→        return $store;
   204→    }
   205→
   206→    # Create Load node (variable read)
   207→    method build_load_node($var_name) {
   208→        my $node_id = $scope->lookup($var_name);
   209→        return undef unless $node_id;
   210→
   211→        # Check if this is a Proj node (parameter) - if so, return it directly
   212→        my $node = $graph->nodes->{$node_id};
   213→        if ($node && $node->op eq 'Proj') {
   214→            # Parameter: return the Proj node directly
   215→            return $node;
   216→        }
   217→
   218→        # Regular variable: create Load node from Store
   219→        my $attributes = {
   220→            name => $var_name,
   221→            store_id => $node_id
   222→        };
   223→        my $load_id = $self->next_node_id();
   224→        my $load = Chalk::IR::Node->new(
   225→            id            => $load_id,
   226→            op            => 'Load',
   227→            inputs        => [$current_control, $node_id],
   228→            attributes    => $attributes,
   229→        );
   230→        $graph->add_node($load);
   231→        return $load;
   232→    }
   233→
   234→    # Create Proj node (projection from MultiNode like Start)
   235→    method build_proj_node($source_node, $index, $label) {
   236→        my $node_id = $self->next_node_id();
   237→        my $proj = Chalk::IR::Node::Proj->new(
   238→            id            => $node_id,
   239→            inputs        => [$source_node->id],
   240→            index         => $index,
   241→            label         => $label,
   242→        );
   243→        $graph->add_node($proj);
   244→        return $proj;
   245→    }
   246→
   247→    # Comparison nodes
   248→    method build_greater_node($left_node, $right_node) {
   249→        my $node_id = $self->next_node_id();
   250→        my $cmp = Chalk::IR::Node::GT->new(
   251→            id            => $node_id,
   252→            inputs        => [$current_control, $left_node->id, $right_node->id],
   253→            left_id       => $left_node->id,
   254→            right_id      => $right_node->id,
   255→        );
   256→        $graph->add_node($cmp);
   257→        return $cmp;
   258→    }
   259→
   260→    method build_less_node($left_node, $right_node) {
   261→        my $node_id = $self->next_node_id();
   262→        my $cmp = Chalk::IR::Node::LT->new(
   263→            id            => $node_id,
   264→            inputs        => [$current_control, $left_node->id, $right_node->id],
   265→            left_id       => $left_node->id,
   266→            right_id      => $right_node->id,
   267→        );
   268→        $graph->add_node($cmp);
   269→        return $cmp;
   270→    }
   271→
   272→    method build_equal_node($left_node, $right_node) {
   273→        my $node_id = $self->next_node_id();
   274→        my $cmp = Chalk::IR::Node::EQ->new(
   275→            id            => $node_id,
   276→            inputs        => [$current_control, $left_node->id, $right_node->id],
   277→            left_id       => $left_node->id,
   278→            right_id      => $right_node->id,
   279→        );
   280→        $graph->add_node($cmp);
   281→        return $cmp;
   282→    }
   283→
   284→    method build_greater_or_equal_node($left_node, $right_node) {
   285→        my $node_id = $self->next_node_id();
   286→        my $cmp = Chalk::IR::Node::GE->new(
   287→            id            => $node_id,
   288→            inputs        => [$current_control, $left_node->id, $right_node->id],
   289→            left_id       => $left_node->id,
   290→            right_id      => $right_node->id,
   291→        );
   292→        $graph->add_node($cmp);
   293→        return $cmp;
   294→    }
   295→
   296→    method build_less_or_equal_node($left_node, $right_node) {
   297→        my $node_id = $self->next_node_id();
   298→        my $cmp = Chalk::IR::Node::LE->new(
   299→            id            => $node_id,
   300→            inputs        => [$current_control, $left_node->id, $right_node->id],
   301→            left_id       => $left_node->id,
   302→            right_id      => $right_node->id,
   303→        );
   304→        $graph->add_node($cmp);
   305→        return $cmp;
   306→    }
   307→
   308→    method build_not_equal_node($left_node, $right_node) {
   309→        my $node_id = $self->next_node_id();
   310→        my $cmp = Chalk::IR::Node::NE->new(
   311→            id            => $node_id,
   312→            inputs        => [$current_control, $left_node->id, $right_node->id],
   313→            left_id       => $left_node->id,
   314→            right_id      => $right_node->id,
   315→        );
   316→        $graph->add_node($cmp);
   317→        return $cmp;
   318→    }
   319→
   320→    # Unary operation nodes
   321→    method build_not_node($operand_node) {
   322→        my $node_id = $self->next_node_id();
   323→        my $not = Chalk::IR::Node::Not->new(
   324→            id            => $node_id,
   325→            inputs        => [$current_control, $operand_node->id],
   326→            operand_id    => $operand_node->id,
   327→        );
   328→        $graph->add_node($not);
   329→        return $not;
   330→    }
   331→
   332→    method build_negate_node($operand_node) {
   333→        my $node_id = $self->next_node_id();
   334→        my $negate = Chalk::IR::Node::Negate->new(
   335→            id            => $node_id,
   336→            inputs        => [$current_control, $operand_node->id],
   337→            operand_id    => $operand_node->id,
   338→        );
   339→        $graph->add_node($negate);
   340→        return $negate;
   341→    }
   342→
   343→    method build_pre_increment_node($operand_node) {
   344→        my $node_id = $self->next_node_id();
   345→        my $pre_inc = Chalk::IR::Node::PreIncrement->new(
   346→            id            => $node_id,
   347→            inputs        => [$current_control, $operand_node->id],
   348→            operand_id    => $operand_node->id,
   349→        );
   350→        $graph->add_node($pre_inc);
   351→        return $pre_inc;
   352→    }
   353→
   354→    method build_pre_decrement_node($operand_node) {
   355→        my $node_id = $self->next_node_id();
   356→        my $pre_dec = Chalk::IR::Node::PreDecrement->new(
   357→            id            => $node_id,
   358→            inputs        => [$current_control, $operand_node->id],
   359→            operand_id    => $operand_node->id,
   360→        );
   361→        $graph->add_node($pre_dec);
   362→        return $pre_dec;
   363→    }
   364→
   365→    method build_post_increment_node($operand_node) {
   366→        my $node_id = $self->next_node_id();
   367→        my $post_inc = Chalk::IR::Node::PostIncrement->new(
   368→            id            => $node_id,
   369→            inputs        => [$current_control, $operand_node->id],
   370→            operand_id    => $operand_node->id,
   371→        );
   372→        $graph->add_node($post_inc);
   373→        return $post_inc;
   374→    }
   375→
   376→    method build_post_decrement_node($operand_node) {
   377→        my $node_id = $self->next_node_id();
   378→        my $post_dec = Chalk::IR::Node::PostDecrement->new(
   379→            id            => $node_id,
   380→            inputs        => [$current_control, $operand_node->id],
   381→            operand_id    => $operand_node->id,
   382→        );
   383→        $graph->add_node($post_dec);
   384→        return $post_dec;
   385→    }
   386→
   387→    method build_reference_node($operand_node) {
   388→        my $node_id = $self->next_node_id();
   389→        my $reference = Chalk::IR::Node::Reference->new(
   390→            id            => $node_id,
   391→            inputs        => [$current_control, $operand_node->id],
   392→            operand_id    => $operand_node->id,
   393→        );
   394→        $graph->add_node($reference);
   395→        return $reference;
   396→    }
   397→
   398→    # Control flow nodes
   399→    method build_if_node($condition_node) {
   400→        my $node_id = $self->next_node_id();
   401→        my $if_node = Chalk::IR::Node::If->new(
   402→            id            => $node_id,
   403→            inputs        => [$current_control, $condition_node->id],
   404→            condition_id  => $condition_node->id,
   405→        );
   406→        $graph->add_node($if_node);
   407→        return $if_node;
   408→    }
   409→
   410→    method build_if_true_node($if_node) {
   411→        my $if_true = $self->build_proj_node($if_node, 0, 'IfTrue');
   412→        return $if_true;
   413→    }
   414→
   415→    method build_if_false_node($if_node) {
   416→        my $if_false = $self->build_proj_node($if_node, 1, 'IfFalse');
   417→        return $if_false;
   418→    }
   419→
   420→    method build_region_node(@control_inputs) {
   421→        my $node_id = $self->next_node_id();
   422→        my $region = Chalk::IR::Node::Region->new(
   423→            id            => $node_id,
   424→            inputs        => \@control_inputs,
   425→        );
   426→        $graph->add_node($region);
   427→        return $region;
   428→    }
   429→
   430→    method build_phi_node($region_node, @value_inputs) {
   431→        my $node_id = $self->next_node_id();
   432→        my $phi = Chalk::IR::Node::Phi->new(
   433→            id            => $node_id,
   434→            inputs        => [$region_node->id, @value_inputs],
   435→            region_id     => $region_node->id,
   436→        );
   437→        $graph->add_node($phi);
   438→        return $phi;
   439→    }
   440→
   441→    # Loop control flow nodes
   442→    method build_loop_node($entry_control = undef) {
   443→        my $ctrl = $entry_control // $current_control // '__CONTROL_PLACEHOLDER__';
   444→        my $node_id = $self->next_node_id();
   445→        my $loop = Chalk::IR::Node::Loop->new(
   446→            id            => $node_id,
   447→            inputs        => [$ctrl],  # Entry control; backedge added later
   448→        );
   449→        $graph->add_node($loop);
   450→        return $loop;
   451→    }
   452→
   453→    method build_loop_phi_node($loop_node, $initial_value, $loop_value = undef) {
   454→        # Loop phi starts with control and initial value
   455→        # Loop value added later (lazy phi pattern)
   456→        my @inputs = ($loop_node->id, $initial_value);
   457→        push @inputs, $loop_value if defined $loop_value;
   458→
   459→        my $node_id = $self->next_node_id();
   460→        my $phi = Chalk::IR::Node::Phi->new(
   461→            id            => $node_id,
   462→            inputs        => \@inputs,
   463→            region_id     => $loop_node->id,
   464→        );
   465→        $graph->add_node($phi);
   466→        return $phi;
   467→    }
   468→
   469→    # Function call nodes
   470→    method build_call_node($function_name, @arg_nodes) {
   471→        # Call: control, memory, arguments...
   472→        # For now, use current_control for both control and memory
   473→        my $attributes = { function => $function_name };
   474→        my $node_id = $self->next_node_id();
   475→        my $call = Chalk::IR::Node->new(
   476→            id            => $node_id,
   477→            op            => 'Call',
   478→            inputs        => [$current_control, $current_control, map { $_->id } @arg_nodes],
   479→            attributes    => $attributes,
   480→        );
   481→        $graph->add_node($call);
   482→        return $call;
   483→    }
   484→
   485→    # Loop-carried dependency tracking methods
   486→    method begin_loop_tracking() {
   487→        # Start tracking loop-carried dependencies
   488→        $loop_entry_scope = $scope->snapshot_bindings();
   489→        $loop_tracking_active = 1;
   490→        return;
   491→    }
   492→
   493→    method end_loop_tracking() {
   494→        # End tracking and clean up
   495→        $loop_entry_scope = undef;
   496→        $loop_tracking_active = 0;
   497→        return;
   498→    }
   499→
   500→    method is_tracking_loop() {
   501→        return $loop_tracking_active;
   502→    }
   503→
   504→    method loop_entry_scope() {
   505→        return $loop_entry_scope;
   506→    }
   507→
   508→    method generate_loop_phi_nodes($loop_node) {
   509→        # Generate phi nodes for all variables modified within the loop
   510→        return {} unless $loop_tracking_active;
   511→        return {} unless defined $loop_entry_scope;
   512→
   513→        # Capture current (loop-end) values before creating phis
   514→        my $loop_end_scope = $scope->snapshot_bindings();
   515→
   516→        # Find which variables were modified in the loop
   517→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   518→
   519→        # Generate a phi node for each modified variable
   520→        my %phis = ();
   521→        for my $var (@modified_vars) {
   522→            my $initial_value = $loop_entry_scope->{$var};
   523→            my $loop_value = $loop_end_scope->{$var};
   524→
   525→            # Create phi with initial value; backedge added later
   526→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   527→            $phis{$var} = $phi;
   528→
   529→            # Update scope to use phi node for this variable
   530→            # This ensures uses after the loop see the phi
   531→            $scope->define($var, $phi->id);
   532→        }
   533→
   534→        return \%phis;
   535→    }
   536→
   537→    # Class and object support nodes (Issue #98 Phase 1)
   538→
   539→    method build_classdef_node($class_name, $fields) {
   540→        # Create ClassDef node for class definition
   541→        my $attributes = {
   542→            name => $class_name,
   543→            fields => $fields,
   544→        };
   545→        my $node_id = $self->next_node_id();
   546→        my $classdef = Chalk::IR::Node->new(
   547→            id            => $node_id,
   548→            op            => 'ClassDef',
   549→            inputs        => [$current_control],
   550→            attributes    => $attributes,
   551→        );
   552→        $graph->add_node($classdef);
   553→        return $classdef;
   554→    }
