   559→        my @input_nodes = ($current_control);
   560→        my %field_value_refs;
   561→
   562→        # Build field references from hash
   563→        for my $field_name (sort( keys( $field_values_hash->%* ) )) {
   564→            my $value_node = $field_values_hash->{$field_name};
   565→            push @input_nodes, $value_node->id;
   566→            $field_value_refs{$field_name} = {
   567→                op => 'NodeRef',
   568→                node_id => $value_node->id
   569→            };
   570→        }
   571→
   572→        my $attributes = {
   573→            class => $class_name,
   574→            field_values => \%field_value_refs
   575→        };
   576→        my $node_id = $self->next_node_id();
   577→        my $new_obj = Chalk::IR::Node->new(
   578→            id            => $node_id,
   579→            op            => 'New',
   580→            inputs        => \@input_nodes,
   581→            attributes    => $attributes,
   582→        );
   583→        $graph->add_node($new_obj);
   584→        return $new_obj;
   585→    }
