   345→        id => 'node_0',
   346→        inputs => [],
   347→        function_name => 'main',
   348→        params => [],
   349→    );
   350→    $graph->add_node($start);
   351→
   352→    my $constant = Chalk::IR::Node::Constant->new(
   353→        id => 'node_1',
