   359→
   360→    my $return = Chalk::IR::Node::Return->new(
   361→        id => 'node_2',
   362→        inputs => ['node_0', 'node_1'],
   363→        value_id => 'node_1',
   364→        control_id => 'node_0',
   365→    );
   366→    $graph->add_node($return);
   367→
   368→    # Linearize the graph
   369→    my @schedule = $graph->linearize();
   370→
   371→    # Verify we have all 3 nodes
