     1→# ABOUTME: Threaded interpreter for executing Sea of Nodes IR graphs
     2→# ABOUTME: Linearizes graph, executes nodes in topological order, returns result
     3→use 5.42.0;
     4→use experimental qw(class);
     5→use utf8;
     6→
     7→class Chalk::IR::Interpreter {
     8→    field $graph :param :reader;
     9→
    10→    method execute() {
    11→        # 1. Linearize graph to get execution order
    12→        my @schedule = $graph->linearize();
    13→
    14→        # 2. Initialize value map and heap
    15→        my %values;
    16→        my %heap;
    17→
    18→        # 3. Execute nodes in order
    19→        for my $node (@schedule) {
    20→            my $node_id = $node->id;
    21→            my $op = $node->op;
    22→
